using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Square.Core.Models;
using Square.Models.Enums;

namespace Square.Models;

public record InventoryAdjustmentGroup
{
    /// <summary>
    /// A unique ID generated by Square for the
    /// <c>InventoryAdjustmentGroup</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("id")]
    [MaxLength(100)]
    public string? Id { get; init; }

    /// <summary>
    /// The inventory adjustment of the composed variation.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("root_adjustment_id")]
    [MaxLength(100)]
    public string? RootAdjustmentId { get; init; }

    /// <summary>
    /// Indicates the state of a tracked item quantity in the lifecycle of goods.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("from_state")]
    public InventoryState? FromState { get; init; }

    /// <summary>
    /// Indicates the state of a tracked item quantity in the lifecycle of goods.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("to_state")]
    public InventoryState? ToState { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
